architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-Šifruoti(k, nonce, msg, aad=room_id)
POST /api/kambariai/{id}/messages {šifro tekstas: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, tekstas, atsakymas į?, gijos_id?, paminėjimai?, išsiųstas_at}
ct = AES-GCM-256-Šifruoti(kambario_raktas, nonce, pt, aad=hex(kambario_id))
viela = CBOR{
  v: 1,
  šifruotas tekstas: hex(ct), // kintamo ilgio
  ne: šešioliktainis (12 B),
  sender_pseudo: hex (16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
išorinis = CBOR{
  šaltinio_mazgas: hex32,
  target_user: int64,
  vidinis_šifro tekstas: baitai,
  inner_nonce: baitai,
  send_at: unix_ms
}
sig = Ed25519-Sign(source_priv, išorinis)
POST /federacija/pristatyti { vokas: išorinis, sig: hex64}

auth.h1_f:
POST /api/authentication/register
  { vartotojo vardas, slaptažodis, x25519_public_key, display_name, phone?, email?, avatar_emoji }

201 atsakymas sukurtas:
  { prieigos_token, refresh_token, user_id, username, ... }

auth.h4_f:
register_begin(): iššūkis = rand(32)
                    Options = { rp.id, user.id, pubKeyCredParams, challenge }
                    grąžinimo parinktys

register_finish(attestavimas):
  patikrinti patvirtinimą pagal TPM / saugaus anklavo šaknis CA
  parduotuvė { kredencialo_id, viešasis_raktas, skaitiklis: 0}

auth.h7_f:
POST /api/autentifikavimas/qr/begin
  → { nonce: 128 bitų šešioliktainis, ttl: 60 }
QR naudingoji apkrova = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify {nonce}
  → užregistruotas naujas įrenginys; JWT grįžo.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(kambario_pseudo_druska, siuntėjo_id)[:16] // 32 šešioliktainis
šifruotas tekstas = AES-GCM-Šifruoti(patalpos_raktas, nonce, CBOR_payload, aad=kambario_id)

Ištraukiamas rėmelis: { tipas:"m", kambarys, žinutė:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {failo pavadinimas, dydis, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {failo_id, url}
TTL nebaigta: 24 val

presence.h1_f:
klientas: pirmą kartą paspaudus klavišą → siųsti {type:"t", būsena:"start"}
         daugiau nesiunčia 3 s, nebent pasikeistų būsena
         10 s po paskutinio klavišo paspaudimo → siųsti {type:"t", būsena:"stop"}
imtuvas: automatinis sustabdymas praėjus 10 s po paskutinio „start“, jei „stop“ neatvyko

presence.h2_f:
POST /api/rooms/{id}/read { last_read_message_id }

if user.hides_receipts:
   nesilaikyti; netransliuoti
   neįteikite šiam vartotojui kitų asmenų kvitų
kitaip:
   UPSERT skaitymo kvitai VALUES (kambario_id, vartotojo_id, pranešimo_id, NOW())
   transliacija {type:"r", kambarys, naudotojas, pranešimo_id}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS transliacija {type:"c", kind:"invite", call_id}
WS transliacija {type:"c", kind:"offer", sdp}
WS transliacija {tipas:"c", rūšis:"atsakymas", sdp}
WS transliacija {tipas: "c", rūšis: "kandidatas", ledas} × N
POST /api/calls/{call_id}/end

federation.h2_f:
vokas = {
  šaltinio_mazgas: hex32,
  target_user : int64,
  vidinis_šifro tekstas: baitai,
  inner_nonce : baitai,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(vokas))
POST /federacija/pristatyti { vokas, ženklas }

gossip.h3_f:
reklama = {pubkey, endpoint, reklamuojamas_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklama))
paskalų apkrova: [..., {ad, sig}, ...]

imtuvas: patikrinkite sig prieš ad.pubkey → store iff ok
papildomas: 2^18 pirmaujančių nulių PoW {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template su {
  atsitiktinis = mūsų atsitiktinis,
  serverio_pavadinimas = mūsų prieglobos pavadinimas (arba ECH),
  session_id = mūsų seanso ID,
}
JA4 = t13d_xxxx_xxxx_xxxx (atitinka esamą stabilią Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {vardas: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(viešasis_raktas_iš_HTTPS_įrašo)
DGA: domenas(t) = bazinis32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
įrankis = sign_tool
įvestis = šaltinio medis, keys/release.key
manifestas = {
  versija: "0.1.0",
  built_at: unix_ms,
  failai: [{kelis, sha256, dydis}, ...]
}
sig = Ed25519-Sign(išleidimo_priv., CBOR(manifestas))
išvestis = INTEGRITY.sig.json = {manifestas, pasirašytas_autojas: pub_hex, sig: sig_hex}

bots.h1_f:
sukurti: POST /api/bots {naudotojo vardas, rodomas_vardas, kodas}
          → {bot_id, token, pubkey}
paleisti: vyksta (korutina mazgo viduje)
      OR išorinis (long-poll /api/bots/{id}/updates, token-auth'd)
pranešimas: {tekstas, parašas: Ed25519-Sign(bot_priv, canonical_msg)}

security.h4_f:
canary.txt (kasdien):
  {data, sig: Ed25519-Sign(release_priv, date)}
klientas patikrina → nėra arba neteisingas ⇒ įtariamas kompromisas

avarinė situacija:
  admin POST /api/admin/revoke-all {reason}
  mazgo transliacijos {tipas:"n", įvykis:"kompromisas", priežastis}
  klientai nuvalo raktus, priverčia iš naujo įkelti

debugging.h2_f:
tarifų histogramos (už maršrutą + metodą):
  vortex_http_requests_total{maršrutas,metodas,būsena}
  vortex_http_request_duration_seconds_bucket{route,method,le}

tinklo lizdo matuokliai:
  vortex_ws_connections{mazgas}
  vortex_ws_fanout_queue_depth{kambaris,naudotojas}

pasirinktiniai skaitikliai:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

